package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {
    /** A number with up to two decimals; negative for a correction. */
    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
    /** A claim number: the sheet-wide 1, 2, ... or <period>-<n> / X-<n>. */
    private static final Pattern NUMBER = Pattern.compile("\\S{1,255}");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ClaimRequest request,
            SettingStore settings, Out<ClaimInput> body, RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        body.set(check(sheetId, request, settings));
    }

    /** The claim form's rules on a typed claim, before anything is stored: the claim as it would be stored
     *  (a blank date is the entry date while it is set, else the sheet's today). */
    static ClaimInput check(String sheetId, ClaimRequest request, SettingStore settings) throws InvalidSheetException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidSheetException("The amount must be a number with up to two decimals");
        }
        String dateText = request.date() == null ? "" : request.date().trim();
        LocalDate date;
        try {
            date = dateText.isEmpty() ? settings.claimDate(sheetId.trim()) : LocalDate.parse(dateText);
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Not a date: " + dateText);
        }
        String note = request.note() == null ? "" : request.note().trim();
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String correctsText = request.corrects() == null ? "" : request.corrects().trim();
        String corrects = null;
        if (value.signum() < 0) {
            if (!NUMBER.matcher(correctsText).matches()) {
                throw new InvalidSheetException("A negative amount must name the number of the settled claim it corrects");
            }
            corrects = correctsText;
        } else if (!correctsText.isEmpty()) {
            throw new InvalidSheetException("Only a negative amount corrects a claim");
        }
        return new ClaimInput(value, date, note, request.user(), corrects);
    }
}
package net.officefloor.hq.app.claim;

/** Body of a claim add or edit, as typed: the amount, the date (blank for the sheet's today), the
 *  note, who makes the change, and the number of the claim a correction corrects (blank for none). */
public record ClaimRequest(String amount, String date, String note, String user, String corrects) {
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated claim add or edit: the date already defaulted to the sheet's today; {@code corrects}
 *  the number of the claim a correction (a negative amount) corrects, null for any other claim. */
public record ClaimInput(BigDecimal amount, LocalDate date, String note, String user, String corrects) {

    public ClaimInput(BigDecimal amount, LocalDate date, String note, String user) {
        this(amount, date, note, user, null);
    }

    /** Whether this is a correction: a negative amount. */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses an edit of a claim that is no longer a draft: an open claim is voided and added anew instead. */
public class CheckClaimDraft {
    public void check(@Val Claim claim) throws InvalidSheetException {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new InvalidSheetException("A " + claim.getStatus() + " claim cannot be edited");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses an edit of a claim another user has locked by opening its editor. */
public class CheckClaimLock {
    public void check(@Val ClaimInput input, @Val Claim claim, ClaimStore store) throws InvalidSheetException {
        if (store.lockedByOther(claim, input.user() == null ? "" : input.user().trim())) {
            throw new InvalidSheetException("The claim is being edited by another user");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses a change to a claim due by a date inside a closed period (the period a claim belongs to is the one its
 *  due-by falls in): editing it or moving it on. */
public class CheckClaimPeriod {
    public void check(@Val Claim claim, PeriodStore periods) throws InvalidSheetException {
        ClaimPeriods.refuseClosed(periods, claim.getSheetId(), claim.getDueBy());
    }
}

